from docx import Document
from docx.shared import Pt
from openpyxl import load_workbook
wb=load_workbook('/tmp/recalc/Memoria_Calculo_Avaluo_Rural_Helechal_Alto.xlsx',data_only=True)
f=lambda v:f"{v:,.0f}".replace(",",".")
T3=wb['3_Terreno']; T3b=wb['3b_Renta_contraste']; T4=wb['4_Construcciones']; T5=wb['5_Resumen']; T6=wb['6_Referencia_IGAC']; T2=wb['2_Mercado']
d=Document(); d.styles['Normal'].font.name='Arial'; d.styles['Normal'].font.size=Pt(10)
H=lambda t,l=1:d.add_heading(t,l); P=d.add_paragraph
def BL(items):
    for s in items: d.add_paragraph(s,style='List Bullet')
def T(rows):
    t=d.add_table(rows=len(rows),cols=len(rows[0])); t.style='Light Grid Accent 1'
    for i,r in enumerate(rows):
        for j,v in enumerate(r): t.cell(i,j).text=str(v)
    d.add_paragraph()
cat=T6['F16'].value; ren=T3b['L8'].value; terr=T3['H7'].value; cons=T4['L10'].value
d.add_heading('INFORME DE AVALÚO COMERCIAL RURAL – MEMORIAS DE CÁLCULO',0)
P('LOTE 1-1 TEQUENDAMA, vereda Helechal Alto, Los Patios (Norte de Santander)\nFecha del informe: 8 de noviembre de 2026\nBase normativa: Resolución IGAC 941 del 31 de julio de 2026 y su Anexo Técnico\nESTADO: PRELIMINAR – SIN VALOR COMERCIAL ADOPTABLE').runs[0].bold=True
p=P('ADVERTENCIA: no se ha podido construir una muestra de mercado real (ver §5). El valor por comparación que arroja el libro de cálculo parte de ofertas ficticias y NO debe usarse. Las referencias reales disponibles son el valor catastral del IGAC y el contraste por renta pecuaria, ambas muy inferiores. El informe no es un avalúo hasta contar con comparables verificados, visita técnica y firma del perito con RAA.'); p.runs[0].bold=True
H('1. Información básica (verificada en el catastro público del IGAC)')
T([['Predio','LOTE 1-1 TEQUENDAMA HELECHAL ALTO'],['Municipio / vereda','Los Patios (54405) / Helechal Alto'],['Matrícula inmobiliaria','260-323861 (verificar con el certificado de tradición)'],['Código catastral (anterior, 20 dígitos)','54405-00-00-0009-0020-000'],['NPN (30 dígitos, catastro multipropósito)','544050000000000090020000000000'],['Destino económico','D – agropecuario'],['Área de terreno catastral','195.355 m² = 19,54 ha (valor usado; antes se supuso 18 ha)'],['Área construida catastral','70 m² (2 habitaciones, 1 piso, tipificación 2, puntaje 16). No figura la piscina; verificar en campo'],['Fuente','Base Catastral Pública del Gestor IGAC 09-2026, Registros 1 y 2 y capa R_TERRENO'],['Solicitante / visita técnica','Por confirmar (visita obligatoria, art. 10 Res. 941/2026)']])
H('2. Marco normativo y metodológico')
BL(['Resolución IGAC 941 de 2026 (31-jul-2026) y su Anexo Técnico: métodos y condiciones de los avalúos. Deroga la Res. 620 de 2008 y el art. 13 e incisos 1-3 del art. 14 de la Res. 898 de 2014 (art. 60). Los avalúos iniciados antes de su vigencia siguen la norma anterior (art. 59). Este avalúo se rige por la 941.',
'Arts. aplicados: 10 (visita técnica), 11 (parámetros, AHT, edad/estado/vida útil), 14 (informe), 17-19 (comparación), 21 (CV rural ≤ 10 %), 46-47 (rurales agropecuarios: costo, comparación y renta; terreno y construcciones por separado).',
'Decreto 1170 de 2015, arts. 2.2.2.3.19 y 2.2.2.3.20; Ley 1673 de 2013 y Decreto 556 de 2014 (RAA).',
'La resolución se leyó por OCR de un PDF escaneado; el Anexo, como texto. Verificar los artículos citados contra el Diario Oficial.'])
H('3. Zonificación oficial y norma de uso del suelo')
P('Según el catastro del IGAC, el predio se divide en tres zonas físicas/económicas. Las capas de Zonas Homogéneas Físicas y Geoeconómicas (vigencia de las zonas: 1-ene-2019) aportan Área Homogénea de Tierra (AHT), norma de uso del suelo, disponibilidad de agua, influencia vial, uso actual y valor catastral por hectárea:')
T([['Zona física/económica','Área (ha)','AHT','Norma de uso (capa IGAC)','Uso actual / agua / vía','Valor catastral $/ha']]+[[ 'ZF008 / ZE012','2,87','09CSd1-38 / 09CSd1qL-38','Agrosilvopastoril-deportiva y turística','Bosques / escasa / regular 4 (sin pavimentar, angosta)','6.000.000'],['ZF014 / ZE014','16,21','10CSe1-30 / 10CSe1qL-30','Recreación turística-agrosilvopastoril','Pastos naturales / escasa / regular 3 (pavimentada, angosta)','3.000.000'],['ZF021 / ZE016','0,46','11MSfqp-23','Agrosilvopastoril-forestal protección-producción','Bosques / escasa / regular 3','1.680.000']])
P('Norma municipal: el Plan Básico de Ordenamiento Territorial de Los Patios (documento publicado por Corponor; es una plantilla sin número ni fecha de acuerdo, con corto plazo desde 2001, por lo que probablemente es del año 2000) incluye la vereda El Helechal en el componente rural y establece categorías de usos (principal, compatible, condicionado y prohibido). Para las zonas pecuarias: uso principal ganadería extensiva (cría, levante, doble propósito, ceba); condicionado: recreación, agroindustria y parcelaciones rurales; prohibidos: usos urbanos, suburbanos e industriales. Para las silvopastoriles, las parcelaciones rurales son condicionadas. Conclusión preliminar: el predio es suelo rural agropecuario con uso recreativo-turístico solo condicionado; no es suelo suburbano ni de expansión. Esto no está confirmado con el acuerdo vigente: hay que solicitar a Planeación Municipal el certificado de uso del suelo (puede existir un EOT/POT posterior).')
H('4. Método de comparación de mercado (arts. 17-21)')
P('Se intentó construir la muestra con anuncios publicados en internet (Fincaraíz: 62 anuncios de Los Patios, Cúcuta, Villa del Rosario, El Zulia y San Cayetano, captura del 8-nov-2026). Ninguno es comparable con un predio agropecuario de ~19,5 ha: son lotes campestres de 100 a 5.400 m² en condominios (≈ $170.000–290.000/m²) o terrenos de expansión de uso mixto o industrial como Los Vados (≈ $550.000/m², cerca de $5.500 millones/ha). Los anuncios y su clasificación están en Estudio_Mercado_Anuncios_Fincaraiz_2026-11-08.xlsx.')
P('Las seis ofertas de las hojas 2 y 3 del libro son EJEMPLOS ficticios (CV 6,96 %) y solo muestran la mecánica de cálculo. Hay que reemplazarlas por ofertas o transacciones reales de fincas agropecuarias de la zona, con fecha, fuente, captura de pantalla, coordenadas, AHT y % de negociación justificado (Anexo §2.1; CV máximo rural 10 %, art. 21).')
H('5. Referencias reales disponibles para el terreno')
T([['Referencia','Valor del terreno ($)','$/ha','Observación'],['Valor catastral IGAC (zonas 2019)',f(cat),f(cat/19.5355),'Referencia oficial, no comercial; sin reajustes posteriores'],['Capitalización de renta pecuaria (supuestos)',f(ren),f(ren/19.5355),'Parámetros supuestos (carga, precio, costos, tasa 7,3 %)'],['Comparación con muestra ficticia',f(terr),f(terr/19.5355),'NO UTILIZABLE']])
P('Las dos referencias reales son del mismo orden de magnitud (≈ $2,5–3,5 millones por hectárea) y están muy por debajo del valor de mercado supuesto en la muestra de ejemplo. Con la norma de uso agropecuario y agua escasa, un valor comercial de decenas de millones por hectárea solo sería defendible con transacciones reales de fincas similares en la zona. Si no existen, el art. 47 exige fundamentar el valor en la capacidad de generar ingresos.')
H('6. Construcciones y anexos – costo de reposición depreciado (Anexo §2.3.4)')
P('FD = (1 − ½(x/n + x²/n²)) × E; VA = Vn × FD. Vivienda con el área catastral (70 m²), que probablemente está desactualizada; la piscina, las cercas, el corral y el reservorio son supuestos del perito pendientes de verificar.')
T([['Ítem','Cant.','Costo nuevo','Edad/Vida','Estado','Valor ($)']]+[[T4.cell(r,2).value[:45],f"{T4.cell(r,3).value:g} {T4.cell(r,4).value}",f(T4.cell(r,5).value),f"{T4.cell(r,6).value}/{T4.cell(r,7).value}",T4.cell(r,9).value,f(T4.cell(r,12).value)] for r in range(5,10)]+[['TOTAL','','','','',f(cons)]])
H('7. Resultado')
P('No se adopta un valor comercial. Con la muestra ficticia el libro arroja un total del orden de $%s millones, que no tiene respaldo. Con las referencias reales, el terreno estaría entre $%s millones (catastral) y $%s millones (renta), más construcciones y anexos por $%s millones, y esas cifras tampoco son un avalúo hasta contar con comparables y visita.'%(f(T5['B7'].value/1e6),f(cat/1e6),f(ren/1e6),f(cons/1e6)))
H('8. Pendientes para el informe definitivo')
BL(['Certificado de tradición y libertad (260-323861): propietario, título, gravámenes, servidumbres.','Certificado de uso del suelo expedido por Planeación Municipal de Los Patios y verificación del POT/EOT vigente.','Visita técnica: medir la vivienda y la piscina, estado de conservación, potreros, agua, accesos y levantamiento de áreas.','Estudio de mercado real de fincas agropecuarias de la zona (inmobiliarias locales, Lonja, oficina de registro).','Datos del solicitante, marco jurídico del encargo, firma y RAA del avaluador; entrega de la información al Observatorio Inmobiliario Catastral (art. 58).','Verificar si la Res. 941/2026 regula la vigencia del avalúo (no la encontré en el texto leído).'])
d.save('Informe_Avaluo_Rural_Helechal_Alto_PRELIMINAR.docx')
